        NSGraphicsContext.current?.saveGraphicsState()
        NSBezierPath(rect: rect).addClip()
        NSColor.systemYellow.withAlphaComponent(0.85).setStroke()
        path.lineWidth = 1
        path.stroke()
        NSGraphicsContext.current?.restoreGraphicsState()
    }
