import AppKit

/// The row marks of the Clip inspector (road map 9 §5, spec §11 CI-7): what
/// the SELECTED action does to one row, in a 14 pt gutter before its label.
///
/// A row's mark is derived from two lists of `"group.key"` paths: the keys
/// its control WRITES — taken from the row's own `ops(read())` at build time,
/// so a write that lands on the action's end patch and one that lands on the
/// base props name the same key — and the keys it only FOLLOWS (Gain follows
/// Volume). Both empty is `.none`, action or no action: a row that says
/// nothing about what it writes (a readout, a Document-tab row) is never
/// marked ⊘ by omission.
enum RowMark: Equatable {
    /// Nothing to say — the gutter stays blank.
    case none
    /// ◆ — the row writes a key the selected action's end patch holds.
    case keyed
    /// ◆ and "at end" — the same, for a discrete control, which switches at
    /// the action's end rather than ramping.
    case keyedAtEnd
    /// ◇ — ANOTHER action keys it; the number is that action's time-order
    /// number (`ActionBands.ordered`).
    case other(Int)
    /// ○ — the row follows a keyed value without writing it.
    case follows
    /// ⊘ — the row writes the clip whatever is selected (CI-3, motion, a
    /// list's length): the selected action cannot animate it.
    case notAnimatable
}

/// A section's marks, folded from its gutters: how many KEYS its rows write
/// that the selected action holds (CI-6's count, so a section's `◆N` agrees
/// with its sub-tab's), whether any row is ◇, whether every row that writes
/// is ⊘, whether the section differs from its default (spec §11 CI-9), and
/// the number of the action it is EDITING — the selected one, when any of
/// its rows animates — which is what turns its Reset slot into Clear.
struct SectionMarks: Equatable {
    var keyed: Int
    var other: Bool
    var allNotAnimatable: Bool
    var differs = false
    var editing: Int? = nil

    static let empty = SectionMarks(keyed: 0, other: false, allNotAnimatable: false)
}

/// A row's default (spec §11 CI-9): the undo name its reset runs under,
/// whether the row differs from its default now, and the ops that put the
/// default back — on the base props, or on the selected action's end.
struct InspectorRowDefault {
    let name: String
    let differs: () -> Bool
    let ops: () -> [ReelOp]

    /// The default a typed row derives from its own `read` and `ops`: the
    /// value `read` answers in `.defaults`, written through `ops`.
    static func derived<T: Equatable>(
        _ binding: InspectorBinding, name: String, read: @escaping () -> T,
        ops: @escaping (T) -> [ReelOp]
    ) -> InspectorRowDefault {
    private let content = NSStackView()
    private(set) var isExpanded = true
    private let summary: (() -> String?)?
    /// An explicit "differs from its default" (spec §11 CI-9), for a section
    /// whose rows do not read the props or whose Reset writes fewer keys
    /// than its rows read; nil folds the rows' own defaults.
    private let differs: (() -> Bool)?
    /// The rows' marks, folded (road map 9 §5) at the end of `init` and on
    /// every `refresh()`.
    private(set) var marks = SectionMarks.empty
    /// "Actions don't animate this" — shown while every row that writes is ⊘.
    private var inertNote: InspectorNoteLabel?
    /// The header's click, after the preference is stored — and nothing else:
    /// `reveal()` and `expandByDefault()` never call it (`KeyedReveal`).
    var didToggle: ((InspectorSection) -> Void)?

    /// `summary` is a closure rather than a string because it is re-read on
    /// every `refresh()`: a collapsed section still has to tell the truth
    /// about the value under it. `defaultExpanded` is the state before the
    /// user has ever touched THIS section — the design opens Transform and
    /// the primary section of a text or shape selection, and closes the rest.
        view.subviews.flatMap { subview -> [InspectorMarkGutter] in
            if let gutter = subview as? InspectorMarkGutter { return [gutter] }
            return gutters(in: subview)
        }
    }

    /// `marks` from the gutters as they stand, then the two things drawn from
    /// it: the ⊘ note and the header. A section is EDITING the selected
    /// action when any of its rows animates; one that none does (Document,
    /// Shape, a ⊘-only section) keeps its Reset, since its edits go to the
    /// clip.
    private func foldMarks() {
        let gutters = Self.gutters(in: content)
        let writing = gutters.filter { !$0.writes.isEmpty }
        let binding = gutters.lazy.compactMap { $0.binding }.first
        marks = SectionMarks(
            keyed: gutters.reduce(into: Set<String>()) { $0.formUnion($1.keyedWrites()) }.count,
            other: gutters.contains {
                if case .other = $0.mark { return true } else { return false }
            },
            allNotAnimatable: !writing.isEmpty
                && writing.allSatisfy { $0.mark == .notAnimatable },
            differs: differs?() ?? gutters.contains { $0.default?.differs() == true },
            editing: gutters.contains { $0.animates } ? binding?.selectedActionNumber : nil)
        inertNote?.refresh()
        header.refresh(summary: summary?(), marks: marks)
    }
}

