/// The audio group. Its six tick values — the two fades, the duck's and the
/// compressor's attack and release — are the one family the Times rule
/// deliberately leaves OFF the frame grid (core/CLAUDE.md): they are
/// envelope lengths sampled at the audio rate rather than positions in the
/// picture, and a 10 ms compressor attack quantised to a video frame would
/// round to nothing. Only the sign is checked, as it is for a motion
/// duration.
pub(crate) fn check_audio(props: &AudioProps) -> Result<(), String> {
    in_range("audio.volume", props.volume, 0.0, MAX_GAIN)?;
    ticks_positive_or_zero("audio.fade_in", props.fade_in)?;
    ticks_positive_or_zero("audio.fade_out", props.fade_out)?;
    if let Some(duck) = &props.duck {
        in_range("audio.duck.level", duck.level, 0.0, 1.0)?;
        ticks_positive_or_zero("audio.duck.attack", duck.attack)?;
        ticks_positive_or_zero("audio.duck.release", duck.release)?;
        ticks_positive_or_zero("audio.duck.pre_roll", duck.pre_roll)?;
        ticks_positive_or_zero("audio.duck.hold", duck.hold)?;
    }
    in_range("audio.pan", props.pan, -1.0, 1.0)?;
    in_range("audio.noise_reduction", props.noise_reduction, 0.0, 1.0)?;
    in_range("audio.isolation", props.isolation, 0.0, 1.0)?;
enum FadeShape: String, Codable, CaseIterable {
    case linear
    case sCurve = "s_curve"
    case plus3Db = "plus_3db"
    case minus3Db = "minus_3db"

    /// The popups' words.
    var title: String {
        switch self {
        case .linear: return "Linear"
        case .sCurve: return "S-Curve"
        case .plus3Db: return "+3 dB"
        case .minus3Db: return "−3 dB"
        }
    }
}
/// Every other clip's envelope is multiplied by `level` over this clip's
/// extent (spec §11), with linear `attack` and `release` ramps — or, in
/// `speech` mode (AU-110, AU-112), over each of its media's speech spans
/// widened by `pre_roll` before and `hold` after. The three keys of format 29
/// are each written only when not their default, in either mode (AU-116).
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct Duck {
    pub level: f64,
    pub attack: Ticks,
    pub release: Ticks,
    #[serde(skip_serializing_if = "DuckMode::is_extent")]
    pub mode: DuckMode,
    #[serde(skip_serializing_if = "is_speech_pad")]
    pub pre_roll: Ticks,
    #[serde(skip_serializing_if = "is_speech_pad")]
    pub hold: Ticks,
}

fn is_speech_pad(ticks: &Ticks) -> bool {
    *ticks == DUCK_SPEECH_PAD
}

impl Default for Duck {
    /// The spec §5.2 example: down to 20 %, 0.5 s in, 1 s out.
    fn default() -> Self {
        Duck {
            level: 0.2,
            attack: 300_000,
            release: 600_000,
            mode: DuckMode::Extent,
            pre_roll: DUCK_SPEECH_PAD,
            hold: DUCK_SPEECH_PAD,
        }
    }
}

